import sys,glob,os,re,sqlite3
from bs4 import BeautifulSoup
td,db=sys.argv[1:]
con=sqlite3.connect('file:'+os.path.abspath(db)+'?mode=ro',uri=True)
rows=con.execute('select id,slug,name,parent_id from career_nodes').fetchall()
by_slug={r[1]:r for r in rows}
children={r[3]:r[0] for r in rows if r[3] is not None}
def breadcrumb(id):
 out=[]; seen=set()
 while id and id not in seen:
  seen.add(id); r=next(x for x in rows if x[0]==id); out.append(r[2]); id=r[3]
 return ' > '.join(reversed(out))
def node(slug,relation='direct_discipline',confidence='high',gap=None):
 r=by_slug[slug]; return (slug,r[0],breadcrumb(r[0]),relation,confidence,gap)
def classify(slug,name):
 s=slug.lower(); n=name.lower()
 if s=='prog-gnm': return node('clinical_nurse','closest_specialization','medium')
 if 'phd' in s or 'doctor-of-philosophy' in s: level='doctoral'
 elif 'diploma' in s or s=='prog-pg-dadr': level='diploma'
 elif any(x in s for x in ['master','m-sc','msc-','mtech','mba','llm','masters','pg-diploma']): level='postgraduate'
 else: level='undergraduate'
 # explicit mapping
 if 'b-e-civil' in s or 'btech-in-civil' in s or 'mtech-in-civil' in s or 'phd-in-civil' in s or 'diploma-in-civil' in s: return node('btech_civil','direct_discipline','high')
