 if 'electronics-and-communication' in s or 'btech-ece' in s: return node('btech_ece','direct_discipline','high')
 if 'vlsi' in s: return node('vlsi_engineer','closest_specialization','medium')
 if 'wireless-and-mobile' in s: return node('telecom_engineer','closest_specialization','medium')
 if 'electrical-electronics' in s or 'btech-eee' in s: return node('btech_electrical','direct_discipline','high') if 'semiconductor' not in s else node('btech_electrical','closest_specialization','medium')
 if 'computer-science' in s or 'm-sc-cs' in s or 'prog-be-in-computer-science' in s or 'prog-mtech-in-computer-science' in s:
  if 'aiml' in s: return node('btech_ai','direct_discipline','high')
  if 'data-science' in s: return node('data_scientist','closest_specialization','medium') if level=='postgraduate' or level=='doctoral' else node('bsc_ds','direct_discipline','high')
  if 'diploma' in s: return node('bca','closest_specialization','medium')
  return node('btech_cs','direct_discipline','high') if level in ('postgraduate','doctoral') else node('bsc_cs','direct_discipline','high') if level=='undergraduate' else node('bca','closest_specialization','medium')
 if 'bca-' in s or 'bachelor-of-computer-application' in s: return node('bca','direct_discipline','high')
