 if 'education' in s or 'masters-of-education' in s: return node('ba_education','direct_discipline','high')
 if 'journalism' in s or 'mass-communication' in s: return node('bjmc','direct_discipline','high')
 if 'physical-education' in s or 'sports' in s: return node('sports_coach','closest_specialization','medium') if 'coaching' in s else node('sports_career','direct_discipline','high')
 if 'tourism-hospitality' in s: return node('hotel_mgmt','direct_discipline','high')
 if 'library' in s: return node('art_social','closest_specialization','low')
 if 'translation' in s: return node('translator_eng','direct_discipline','high')
 if 'english' in s: return node('ba_english','direct_discipline','high')
 if 'history' in s: return node('ba_history','direct_discipline','high')
 if 'political-science' in s: return node('ba_polsci','direct_discipline','high')
 if 'psychology' in s: return node('clinical_psychologist','direct_discipline','high')
